window.createSharingUI=function(ctx){
 const {api,esc,modal,button,documentView,download,notify}=ctx;
 let current=null;
 async function action(name,id){if(name==='document-share'){const payload=await api('documents/share?id='+encodeURIComponent(id));current={id,...payload};modal('Share '+payload.number,'<p class="hint">Choose a recipient and review the message before sending. This app runs locally, so its browser address cannot be shared with customers.</p><div class="form-grid"><label class="field">Email<input id="share-email" type="email" value="'+esc(payload.email)+'"></label><label class="field">WhatsApp number with country code<input id="share-phone" type="tel" value="'+esc(payload.phone)+'" placeholder="Example: +91…"></label><label class="field wide">Message<textarea id="share-text" rows="10">'+esc(payload.text)+'</textarea></label></div><div class="form-actions">'+button('Copy message','share-copy')+button('Email draft','share-email')+button('WhatsApp draft','share-whatsapp')+button('Download document','share-download')+button('Print / save PDF','share-pdf')+'</div><p class="hint">Email and WhatsApp open a draft for you to send. Download the document or save it as PDF, then attach it manually. No message is sent automatically.</p>');return true;}
 if(!name.startsWith('share-'))return false;if(!current)throw Error('Open a document sharing dialog first.');
 const text=document.querySelector('#share-text')?.value||current.text;
 if(name==='share-copy'){try{await navigator.clipboard.writeText(text);notify('Message copied.');}catch{document.querySelector('#share-text')?.select();notify('Select the message and press Ctrl+C to copy it.');}}
 if(name==='share-email'){const email=document.querySelector('#share-email').value.trim();if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Enter a valid recipient email.');location.href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(current.subject)+'&body='+encodeURIComponent(text);}
 if(name==='share-whatsapp'){const phone=document.querySelector('#share-phone').value.replace(/[\s()+-]/g,'');if(phone&&!/^\d{8,15}$/.test(phone))throw Error('Use a full phone number with country code, or leave it blank to choose a chat.');window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}
 if(name==='share-pdf'){documentView(current.id);window.print();}
 if(name==='share-download'){documentView(current.id);const paper=document.querySelector('.document-paper').outerHTML;const html='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(current.number)+'</title><style>body{font:14px Arial,sans-serif;color:#20324b;max-width:850px;margin:40px auto;padding:20px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #ddd;padding:10px}p{white-space:pre-line;line-height:1.6}.document-header,.document-meta{display:flex;justify-content:space-between;gap:30px}.document-totals{margin:24px 0 24px auto;max-width:300px}.document-totals div{display:flex;justify-content:space-between;padding:6px}.grand{font-weight:bold}.document-brand{text-align:center;margin-top:40px;font-size:11px}@media print{body{margin:0}}</style></head><body>'+paper+'</body></html>';download(current.number.replace(/[^a-z0-9-]/gi,'_')+'.html',html,'text/html');notify('Document downloaded. Attach it to your email or WhatsApp message.');}
 return true;
 }
 return {action};
};
